package main

import (
	"fmt"
	"io"
	"strings"
)

type UpperReader struct {
	src io.Reader
}

func (u *UpperReader) Read(p []byte) (int, error) {
	n, err := u.src.Read(p)
	if n > 0 {
		for i := 0; i < n; i++ {
			if p[i] >= 'a' && p[i] <= 'z' {
				p[i] = p[i] - 32
			}
		}
	}
	return n, err
}

func main() {
	reader := &UpperReader{src: strings.NewReader("hello go!")}
	data := make([]byte, 100)
	n, _ := reader.Read(data)
	fmt.Println(string(data[:n]))
}

